-- TAFSD-524 / TAFSD-525: a schedule remembers which of the school's sheets its
-- Excel export copies, and admins start schedules from presets.

-- Null on existing schedules: the export takes the layout from their classes.
ALTER TABLE "exam_schedules" ADD COLUMN "layout" VARCHAR(20);

-- CreateTable
CREATE TABLE "exam_schedule_presets" (
    "id" SERIAL NOT NULL,
    "name" VARCHAR(150) NOT NULL,
    "layout" VARCHAR(20) NOT NULL,
    "title" VARCHAR(150) NOT NULL,
    "segment_line" VARCHAR(150),
    "class_ids" INTEGER[] DEFAULT ARRAY[]::INTEGER[],
    "rows" JSONB NOT NULL DEFAULT '[]',
    "notes" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "created_by" VARCHAR(100),
    "created_at" TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(6) NOT NULL,

    CONSTRAINT "exam_schedule_presets_pkey" PRIMARY KEY ("id")
);

-- The school's own sheets for 2026-2027, as the first presets. The notes keep
-- this term's dates; the admin updates them on the schedule.

INSERT INTO "exam_schedule_presets" ("name", "layout", "title", "segment_line", "class_ids", "rows", "notes", "sort_order", "created_by", "updated_at") VALUES (
    'Preliminary Assessments — IX & X', 'SECONDARY', 'PRELIMINARY ASSESSMENTS', NULL, ARRAY[18, 19]::INTEGER[],
    '[{"time": "8:00 - 11:30", "cells": {"18": "PHYSICS PRACTICAL", "19": "CHEMISTRY PRACTICAL"}}, {"time": "8:00 - 11:30", "cells": {"18": "CHEMISTRY PRACTICAL", "19": "PHYSICS PRACTICAL"}}, {"time": "8:00 - 11:30", "cells": {"18": "BIOLOGY / COMPUTER PRACTICAL", "19": "BIOLOGY / COMPUTER PRACTICAL"}}, {"time": "8:00 - 11:30", "cells": {"18": "PHYSICS THEORY", "19": "BIOLOGY / COMPUTER THEORY"}}, {"time": "8:00 - 11:30", "cells": {"18": "ISLAMIAT", "19": "ENGLISH"}}, {"time": "8:00 - 11:30", "cells": {"18": "MATHEMATICS", "19": "MATHEMATICS"}}, {"time": "8:00 - 11:30", "cells": {"18": "URDU", "19": "CHEMISTRY THEORY"}}, {"time": "8:00 - 11:30", "cells": {"18": "CHEMISTRY THEORY", "19": "SINDHI"}}, {"time": "8:00 - 11:30", "cells": {"18": "ENGLISH", "19": "PAKISTAN STUDIES"}}, {"time": "8:00 - 11:30", "cells": {"18": "BIOLOGY / COMPUTER THEORY", "19": "PHYSICS THEORY"}}]'::jsonb,
    ARRAY['ADMIT CARDS WILL BE ISSUED ON WEDNESDAY, DECEMBER 09, 2026, SUBJECT TO THE CLEARANCE OF DUES TILL DECEMBER 2026.', 'IN FAILURE TO BRING ADMIT CARD, NO STUDENT WILL BE ALLOWED TO APPEAR IN THE PRELIMINARY ASSESSMENTS.', 'IN CASE OF SCHOOL''S CLOSURE DUE TO ANY CITY DISTURBANCE, THE ASSESSMENT OF THAT DAY WILL BE ASSESSED AFTER THE LAST SCHEDULED ASSESSMENT.', 'NO PRE OR POST ASSESSMENT WILL BE CONDUCTED.', 'KINDLY REVIEW THE WORK DONE WITH YOUR CHILD SO THAT HE / SHE MAY ACHIEVE THE BEST GRADE.', 'RESOURCE MATERIALS : LECTURES, TEXT BOOKS, REFERENCE BOOKS, REGISTERS / NOTE BOOKS.', 'NO LENDING OR BORROWING WILL BE ALLOWED, STUDENTS HAVE TO BRING TRANSPARENT POUCHES FOR THEIR STATIONERY.', 'NO BAGS AND NOTEBOOKS ARE ALLOWED DURING THE ASSESSMENTS IN THE CAMPUS.', 'USAGE OF ASSESSMENT BOARD IS NOT ALLOWED.', 'THE RESULT WILL BE ANNOUNCED ON SATURDAY, JANUARY 15, 2027 , IN SHA ALLAH.', 'KINDLY CLEAR THE OUTSTANDING DUES TILL DECEMBER 2026 ON OR BEFORE, TUESDAY, DECEMBER 08, 2026 IF THERE ARE ANY, OTHERWISE THE ADMIT CARD OF THE PRELIMINARY WILL NOT BE ISSUED TO APPEAR IN HIS / HER PRELIMINARY ASSESSMENTS 2026 – 2027.']::TEXT[],
    10, 'system', CURRENT_TIMESTAMP);

